use std::cmp::Reverse;
use std::io::{self, BufRead};

fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines().map(|l| l.unwrap());

    let t: usize = lines.next().unwrap().parse().unwrap();
    for _ in 0..t {
        let nm: Vec<usize> = lines.next().unwrap().split_whitespace().map(|s| s.parse().unwrap()).collect();
        let n = nm[0];
        let m = nm[1];

        let mut a: Vec<Vec<char>> = Vec::with_capacity(n);
        for _ in 0..n {
            let line = lines.next().unwrap();
            a.push(line.chars().collect());
        }

        let mut b: Vec<i32> = Vec::with_capacity(n * (n - 1) / 2);
        for i in 0..n {
            for j in i + 1..n {
                let mut sum = 0;
                for k in 0..m {
                    let c = if a[i][k] < a[j][k] {
                        a[j][k] as i32 - a[i][k] as i32
                    } else {
                        a[i][k] as i32 - a[j][k] as i32
                    };
                    sum += c;
                }
                b.push(sum);
            }
        }

        b.sort_by_key(|&x| Reverse(x));
        println!("{}", b[0]);
    }
}

