fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();

    let t: usize = lines.next().unwrap().unwrap().parse().unwrap();
    for _ in 0..t {
        let n: usize = lines.next().unwrap().unwrap().parse().unwrap();
        let a: Vec<i32> = lines.next().unwrap().unwrap()
            .split_whitespace()
            .take(n)
            .map(|s| s.parse().unwrap())
            .collect();

        let m: usize = lines.next().unwrap().unwrap().parse().unwrap();
        let b: Vec<i32> = lines.next().unwrap().unwrap()
            .split_whitespace()
            .take(m)
            .map(|s| s.parse().unwrap())
            .collect();

        let mut a = a;
        let mut b = b;
        a.sort();
        b.sort();

        match a[n - 1].cmp(&b[m - 1]) {
            Ordering::Greater => println!("Alice\nAlice"),
            Ordering::Less => println!("Bob\nBob"),
            Ordering::Equal => println!("Alice\nBob"),
        }
    }
}

