        x.push(xi);
        d.push(di);
    }

    let mut c = 0;
    for (i, &xi) in x.iter().enumerate() {
        for (j, &xj) in x.iter().enumerate() {
            if i != j {
                if xi + d[i] == xj && xj + d[j] == xi {
                    c = 1;
                    break;
                }
            }
        }
        if c == 1 {
            break;
        }
    }

    if c == 1 {
        println!("YES");
    } else {
        println!("NO");
    }
