    let first_line: Vec<i32> = lines.next().unwrap().split_whitespace()
        .map(|s| s.parse().unwrap()).collect();
    let (mut s, n) = (first_line[0], first_line[1] as usize);

    let mut a = Vec::with_capacity(n);
    let mut b = Vec::with_capacity(n);

    for _ in 0..n {
        let line: Vec<i32> = lines.next().unwrap().split_whitespace()
            .map(|s| s.parse().unwrap()).collect();
        a.push(line[0]);
        b.push(line[1]);
    }

    for i in 0..n-1 {
        for j in 0..n-i-1 {
            if a[j] > a[j+1] {
                a.swap(j, j+1);
                b.swap(j, j+1);
            }
        }
    }

    for i in 0..n {
        if s > a[i] {
            s += b[i];
        } else {
            println!("NO");
            return;
        }
    }
    println!("YES");
