#include <stdio.h>
#include <stdlib.h>

#define N 100001 

long long dp[N];
int fv[N];

int main()
{
    int n, nr, i, maxim;
    scanf( "%d", &n );
    maxim = 0;
    for ( i = 0; i < n; i++ ) {
      scanf( "%d", &nr );
      fv[nr]++;
      if ( maxim < nr )
        maxim = nr;
    }
    dp[1] = fv[1];
    for ( i = 2; i <= maxim; i++ ) {
      if( dp[i - 1] > dp[i - 2] + (long long)i * fv[i] )
        dp[i] = dp[i - 1];
      else
        dp[i] = dp[i - 2] + (long long)i * fv[i];
    }
    printf("%I64d", dp[maxim]);
    return 0;
}

