    let mut lines = input.lines();
    let n: usize = lines.next().unwrap().parse().unwrap();
    let mut fv = vec![0; 100001];
    let mut maxim = 0;

    for line in lines.take(n) {
        let nr: usize = line.parse().unwrap();
        fv[nr] += 1;
        if maxim < nr {
            maxim = nr;
        }
    }

    let mut dp = vec![0; maxim + 1];
    dp[1] = fv[1] as i64;

    for i in 2..=maxim {
        dp[i] = dp[i - 1].max(dp[i - 2] + (i as i64 * fv[i] as i64));
    }

    println!("{}", dp[maxim]);
}

