ll left, right;
int i;

int main ()
{
	s = (char *)(malloc(MAX)); p = s;
	left = right =  0; i = 0;

	scanf ( "%s", s );

	while ( *s != '^' ) ++ s;

	while ( s != p )
	{
		-- s; ++ i;
		if ( *s >= '0' && *s <= '9' )
			left += (*s-'0') * i;
	}

	while ( *s != '^' ) ++ s; i = 0;

	while ( *s )
	{
		++ s; ++ i;
		if ( *s >= '0' && *s <= '9' )
			right += (*s-'0') * i;
	}

