                        }
                        a.sort();
                        let min = a[0];
                        let step = min * 2 - 1;
                        sum[j] = 0;
                        for &num in a.iter().rev() {
                            if num >= step {
                                sum[j] += if num % step == 0 {
                                    num / step - 1
                                } else {
                                    num / step
                                };
                            }
                        }
                        j += 1;
                    }
                }
            }
        }
