        }
        for (int i = 0; i < r; i++){
            scanf("%i", &c);
            cr[c - 1]++;
        }
        for (int i = 0; i < n; i++)
            if (cl[i] && cr[i]){
                min = cl[i] < cr[i]? cl[i]: cr[i];
                cl[i] -= min;
                cr[i] -= min;
                l -= min;
                r -= min;
            }
        if (l < r){
            SWAP(cl, cr, int *);
            SWAP(l, r, int);
        }
        for (int i = 0; i < n; i++){
            c = cl[i] - cl[i] % 2;
            min = (l - r) < c? l - r: c;
            count += min / 2;
            l -= min;
        }
