                let next = j + segment;
                let new_d = d[j] + 1;
                let last_dig = digits[last[next]];

                if new_d > d[next] || (new_d == d[next] && curr_dig > last_dig) {
                    d[next] = new_d;
                    last[next] = segment;
                }
            }
        }
    }

    let mut start = 0;
    for i in 1..=n {
        if d[i] > d[start] || (d[i] == d[start] && segments[last[i]] > segments[last[start]]) {
            start = i;
        }
    }

    let mut result = String::new();
    while start != 0 {
        result.push_str(&digits[last[start]].to_string());
        start -= last[start];
    }

    println!("{}", result.chars().rev().collect::<String>());
}

