            .map(|s| s.parse().unwrap()).collect();
        let (l, r) = (query[0], query[1]);
        let ans = values[l - 1] - 1 + 2 * (diffs[r - 1] - diffs[l - 1]) + k as i32 - values[r - 1];
        println!("{}", ans);
    }
}

