use std::io::{self, Read};

fn main() -> io::Result<()> {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input)?;

    let s = input.trim();
    let n = s.len();
    let mut cnt = [0; 26];

    for c in s.chars() {
        cnt[(c as u8 - b'a') as usize] += 1;
    }

    let mut mn = 0;
    while cnt[mn] == 0 {
        mn += 1;
    }

    let mut ans = String::with_capacity(n);
    let mut tmp = String::with_capacity(n);

    for c in s.chars() {
        let idx = (c as u8 - b'a') as usize;
        if idx == mn {
            ans.push(c);
        } else {
            tmp.push(c);
        }

        cnt[idx] -= 1;
        if cnt[mn] == 0 {
            while mn < 26 && cnt[mn] == 0 {
                mn += 1;
            }
            while let Some(last) = tmp.pop() {
                if (last as u8 - b'a') as usize <= mn {
                    ans.push(last);
                } else {
                    tmp.push(last);
                    break;
                }
            }
        }
    }

    while let Some(last) = tmp.pop() {
        ans.push(last);
    }

    println!("{}", ans);
    Ok(())
}

