    let m: usize = lines.next().unwrap().parse().unwrap();
    let mut add = vec![0.0; 212345];
    let mut v = vec![0.0; 212345];
    let mut n = 1;
    let mut res = 0.0;

    for _ in 0..m {
        let query: Vec<i32> = lines.next().unwrap().split_whitespace()
            .map(|s| s.parse().unwrap()).collect();
        match query[0] {
            1 => {
                let a = query[1] as usize;
                let x = query[2] as f64;
                res += a as f64 * x;
                add[a - 1] += x;
            },
            2 => {
                let x = query[1] as f64;
                v[n] = x;
                res += x;
                n += 1;
            },
            3 => {
                n -= 1;
                res -= v[n] + add[n];
                add[n - 1] += add[n];
                add[n] = 0.0;
            },
            _ => unreachable!(),
        }
        let ans = res / n as f64;
        println!("{:.6}", ans);
    }
}

