    let mut ch = vec![vec![0; K + 1]; N + 1];
    let mut ff = vec![0; K + 1];

    dp[0][0] = 1;
    for k in 1..=K {
        for n in 1..=N {
            let mut x = 0;
            for a in 1.. {
                let m = n as isize - a as isize * k as isize;
                if m < 0 {
                    break;
                }
                x = (x + dp[k - 1][m as usize]) % MD;
            }
            dp[k][n] = x;
        }
    }

    ff[0] = 1;
    let mut f = 1;
    for k in 0..=K {
        ff[k] = f;
        f = (f as usize * (k + 1)) % MD;
    }

    ch[0][0] = 1;
    for n in 1..=N {
        ch[n][0] = 1;
        for k in 1..=K {
            ch[n][k] = (ch[n - 1][k] + ch[n - 1][k - 1]) % MD;
        }
    }

    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
