        let (n, k) = (nk[0], nk[1]);
        let mut ans = 0;
        if k <= K {
            for l in k..=n {
                ans = (ans + dp[k][l] * ff[k] % MD * ch[n - l + k][k]) % MD;
            }
        }
        println!("{}", ans);
    }
}

