    let mut dp = vec![vec![0; 4]; n + 1];
    dp[0][0] = 1;

    for (i, (&c1, &c2)) in s1.iter().zip(s2.iter()).enumerate() {
        for j in 0..4 {
            if dp[i][j] == 0 {
                continue;
            }

            match (c1, c2) {
                ('?', '?') => {
                    dp[i + 1][j] = (dp[i + 1][j] + dp[i][j] * 10) % M;
                    dp[i + 1][j | 1] = (dp[i + 1][j | 1] + dp[i][j] * 45) % M;
                    dp[i + 1][j | 2] = (dp[i + 1][j | 2] + dp[i][j] * 45) % M;
                },
                ('?', _) => {
                    dp[i + 1][j] = (dp[i + 1][j] + dp[i][j]) % M;
                    dp[i + 1][j | 1] = (dp[i + 1][j | 1] + dp[i][j] * (9 - c2 as i64 + 48)) % M;
                    dp[i + 1][j | 2] = (dp[i + 1][j | 2] + dp[i][j] * (c2 as i64 - 48)) % M;
                },
                (_, '?') => {
                    dp[i + 1][j] = (dp[i + 1][j] + dp[i][j]) % M;
                    dp[i + 1][j | 1] = (dp[i + 1][j | 1] + dp[i][j] * (c1 as i64 - 48)) % M;
                    dp[i + 1][j | 2] = (dp[i + 1][j | 2] + dp[i][j] * (9 - c1 as i64 + 48)) % M;
                },
                (_, _) => {
                    if c1 == c2 {
                        dp[i + 1][j] = (dp[i + 1][j] + dp[i][j]) % M;
                    } else if c1 > c2 {
                        dp[i + 1][j | 1] = (dp[i + 1][j | 1] + dp[i][j]) % M;
                    } else {
                        dp[i + 1][j | 2] = (dp[i + 1][j | 2] + dp[i][j]) % M;
                    }
                }
            }
        }
    }

    println!("{}", dp[n][3]);
}

