{
	for (int i = 0; i < Maxn; i++) {
		C[i][0] = C[i][i] = 1;
		for (int j = 1; j < i; j++)
			C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % mod;
	}
	dp[0][0] = 1;
	for (int i = 1; i < Maxn; i++)
		for (int j = 0; j < Maxm; j++)
			for (int k = i; j - k >= 0; k += i) {
				dp[i][j] = (dp[i][j] + dp[i - 1][j - k]) % mod;
			}
