#include <stdio.h>

#define Maxn 1005
#define Maxm 2005
#define mod 1000000007

int C[Maxn][Maxn];
int dp[Maxn][Maxm];
int fac[Maxn];
int t;
int n, k;

int main()
{
	for (int i = 0; i < Maxn; i++) {
		C[i][0] = C[i][i] = 1;
		for (int j = 1; j < i; j++)
			C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % mod;
	}
	dp[0][0] = 1;
	for (int i = 1; i < Maxn; i++)
		for (int j = 0; j < Maxm; j++)
			for (int k = i; j - k >= 0; k += i) {
				dp[i][j] = (dp[i][j] + dp[i - 1][j - k]) % mod;
			}
	fac[0] = 1;
	for (int i = 1; i < Maxn; i++)
		fac[i] = (long long) i * fac[i - 1] % mod;
	scanf("%d", &t);
	while (t--) {
		scanf("%d %d", &n, &k);
		long long int res = 0;
		for (int i = 0; i <= n - 1; i++)
		    if(n - 1 - i >= k - 1)
		        res = (res + (long long)(dp[k][i + k]) * C[n-i][n-i - k]) % mod;
		res = (long long) res * fac[k] % mod;
		printf("%lld\n", res);
	}
	return 0;
}

