	for (k = 1; k <= K; k++)
		for (n = 1; n <= N; n++) {
			int m, x = 0;

			for (a = 1; (m = n - a * k) >= 0; a++)
				x = (x + dp[k - 1][m]) % MD;
			dp[k][n] = x;
