	for (k = 0, f = 1; k <= K; k++) {
		ff[k] = f;
		f = (long long) f * (k + 1) % MD;
	}
	ch[0][0] = 1;
	for (n = 1; n <= N; n++) {
		ch[n][0] = 1;
		for (k = 1; k <= K; k++)
