	int i, j;
	long long maxinc = 0;

	scanf("%d", &n);
	for (i = 0; i < n; ++i) scanf("%d", a + i);
	for (i = 0; i < n; ++i) scanf("%d", b + i);

	for (i = 1; i <= n; ++i) {
		ps[i] = ps[i - 1] + (long long)a[i - 1] * b[i - 1];
