            rs[j] = rs[j - 2]
                + a[i - j] as i64 * b[i - 1] as i64
                + a[i - 1] as i64 * b[i - j] as i64;

            let inc = rs[j] - (ps[i] - ps[i - j]);
            if inc > maxinc {
                maxinc = inc;
            }
        }
        rs[1] = a[i - 1] as i64 * b[i - 1] as i64;
    }

