            let product = a * b;
            pp[product] += if a == b {
                kk[a] as i64 * (kk[b] as i64 - 1)
            } else {
                kk[a] as i64 * kk[b] as i64 * 2
            };
        }
    }

    for a in 1..=A {
        pp[a] += pp[a - 1];
    }

    let m: usize = lines.next().unwrap().parse().unwrap();
    for _ in 0..m {
        let p: usize = lines.next().unwrap().parse().unwrap();
        println!("{}", n as i64 * (n as i64 - 1) - pp[p - 1]);
