        c[i][0] = 1;
        if i > 0 {
            c[i][i] = 1;
        }
        for j in 1..i {
            c[i][j] = (c[i - 1][j - 1] + c[i - 1][j]) % MOD;
        }
    }

    dp[0][0] = 1;
    for i in 1..MAXN {
        for j in 0..MAXM {
            for k in (i..=j).step_by(i) {
                dp[i][j] = (dp[i][j] + dp[i - 1][j - k]) % MOD;
            }
        }
    }

    fac[0] = 1;
    for i in 1..MAXN {
