use std::cmp::Ordering;

const EPS: f64 = 1e-9;

#[derive(Debug, Default, Clone, Copy)]
struct Zxf {
    c: f64,
    num: usize,
}

fn main() {
    let mut input = String::new();
    std::io::stdin().read_line(&mut input).unwrap();
    let mut parts = input.split_whitespace();
    let n: usize = parts.next().unwrap().parse().unwrap();
    let w: f64 = parts.next().unwrap().parse().unwrap();
    let m: usize = parts.next().unwrap().parse().unwrap();

    let mut ans = vec![vec![Zxf::default(); 1005]; 1005];
    let mut l = vec![0; 10005];
    let mut r = vec![0; 10005];
    let mut tot = vec![0; 10005];
    let mut now = vec![vec![0.0; 10005]; 3];

    let mut n1 = 1;
    let mut m1 = 1;
    l[1] = 1;
    let ar = n as f64 * w / m as f64;

    while n1 <= n && m1 <= m {
        let o = gmin(w - now[1][n1], ar - now[2][m1]);
        tot[m1] += 1;
        ans[m1][tot[m1]] = Zxf { c: o, num: n1 };
        now[1][n1] += o;
        now[2][m1] += o;

        if (now[1][n1] - w).abs() <= EPS {
            r[n1] = m1;
            n1 += 1;
            if (now[2][m1] - ar).abs() <= EPS {
                m1 += 1;
            }
            if n1 <= n {
                l[n1] = m1;
            }
        }
        if (now[2][m1] - ar).abs() <= EPS {
            m1 += 1;
        }
    }

    for i in 1..=n {
        if r[i] - l[i] >= 2 {
            println!("NO");
            return;
        }
    }
    println!("YES");

    for i in 1..=m {
        for j in 1..=tot[i] {
            print!("{} {:.10} ", ans[i][j].num, ans[i][j].c);
        }
        println!();
    }
}

fn gmin(a: f64, b: f64) -> f64 {
    match a.partial_cmp(&b) {
        Some(Ordering::Less) => a,
        _ => b,
    }
}

