int main()
{
    int R , x1 , y1 , x2 , y2;
    double r , xwifi , ywifi;
    scanf("%d%d%d%d%d" , &R , &x1 , &y1 , &x2 , &y2 );

    double abs_x_diff = fabs(x2-x1);
    double abs_y_diff = fabs(y2-y1);

    if ( pow( abs_x_diff* abs_x_diff + abs_y_diff*abs_y_diff , 0.5)  >= R )
    {
        printf("%.1f %.1f %.1f" , (double)x1 , (double)y1 ,(double) R);
        return 0;
    }

    if( x1 == x2 && y1 == y2)
    {
        printf("%.1f %.1f %.1f", ((double)2*x1+R)/2 , (double)y1, ((double)R)/2);
        return 0;
    }

    double angle = asin( abs_y_diff / pow( abs_x_diff* abs_x_diff + abs_y_diff*abs_y_diff , 0.5)  );
    r =  ( pow( abs_x_diff* abs_x_diff + abs_y_diff*abs_y_diff , 0.5) + R ) / 2 ;

    if( x2 < x1 )
        xwifi = x2 + r*cos(angle) ;
    else
        xwifi = x2 - r*cos(angle) ;

    if( y2 < y1 )
        ywifi = y2 + r*sin(angle) ;
    else
        ywifi = y2 - r*sin(angle) ;

    printf("%.15f %.15f %.15f" , xwifi ,ywifi , r);
    return 0;
}

