use std::f64;

fn main() {
    let mut input = String::new();
    std::io::stdin().read_line(&mut input).expect("Failed to read line");
    let mut iter = input.split_whitespace().map(|s| s.parse::<i32>().unwrap());

    let r = iter.next().unwrap();
    let x1 = iter.next().unwrap();
    let y1 = iter.next().unwrap();
    let x2 = iter.next().unwrap();
    let y2 = iter.next().unwrap();

    let abs_x_diff = (x2 - x1).abs() as f64;
    let abs_y_diff = (y2 - y1).abs() as f64;

    let distance = (abs_x_diff * abs_x_diff + abs_y_diff * abs_y_diff).sqrt();

    if distance >= r as f64 {
        println!("{:.1} {:.1} {:.1}", x1 as f64, y1 as f64, r as f64);
        return;
    }

    if x1 == x2 && y1 == y2 {
        println!("{:.1} {:.1} {:.1}", (2.0 * x1 as f64 + r as f64) / 2.0, y1 as f64, r as f64 / 2.0);
        return;
    }

    let angle = abs_y_diff.atan2(abs_x_diff);
    let r = (distance + r as f64) / 2.0;

    let xwifi = if x2 < x1 { x2 as f64 + r * angle.cos() } else { x2 as f64 - r * angle.cos() };
    let ywifi = if y2 < y1 { y2 as f64 + r * angle.sin() } else { y2 as f64 - r * angle.sin() };

    println!("{:.15} {:.15} {:.15}", xwifi, ywifi, r);
}

