fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();

    let first_line = lines.next().unwrap().unwrap();
    let mut parts = first_line.split_whitespace();
    let n: usize = parts.next().unwrap().parse().unwrap();
    let vb: i32 = parts.next().unwrap().parse().unwrap();
    let vs: i32 = parts.next().unwrap().parse().unwrap();

    let mut bus = vec![0; n + 1];
    let second_line = lines.next().unwrap().unwrap();
    let bus_parts: Vec<i32> = second_line.split_whitespace().map(|s| s.parse().unwrap()).collect();
    for (i, &value) in bus_parts.iter().enumerate() {
        bus[i + 1] = value;
    }

    let third_line = lines.next().unwrap().unwrap();
    let mut parts = third_line.split_whitespace();
    let x: i32 = parts.next().unwrap().parse().unwrap();
