        let dd = ((bus[i] - x) as f64).hypot(y as f64);
        let tt = dd / vs as f64 + bus[i] as f64 / vb as f64;

        if tt <= bt && dd < bd {
            bt = tt;
            bi = i;
            bd = dd;
        }
    }

