    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();
    if let Some(Ok(n_str)) = lines.next() {
        let mut n: i32 = n_str.parse().unwrap();
        while n > 0 {
            if let Some(Ok(s)) = lines.next() {
                let mut res = [0; 26];
                let chars: Vec<char> = s.chars().collect();
                let mut i = 0;
                while i < chars.len() {
                    if i + 1 < chars.len() {
                        let a = chars[i] as u8 - b'a';
                        let b = chars[i + 1] as u8 - b'a';
                        if a == b && (res[a as usize] == 2 || res[a as usize] == 0) {
                            res[a as usize] = 0;
                            i += 2;
                            continue;
                        } else {
                            if res[b as usize] == 1 {
                                res[a as usize] = 1;
                            } else {
                                res[a as usize] = 1;
                                res[b as usize] = 2;
                            }
                            i += 1;
                            continue;
                        }
                    }
                    i += 1;
                }
                for (i, &value) in res.iter().enumerate() {
                    if value == 1 || value == 2 {
                        print!("{}", (i as u8 + b'a') as char);
                    }
                }
                println!();
            }
            n -= 1;
        }
    }
}

