    visited[pos] = true;

    loop {
        pos = if direction[pos] == '>' {
            pos + step[pos] as usize
        } else {
            pos - step[pos] as usize
        };

        if pos >= n || pos >= direction.len() || pos >= step.len() || pos >= visited.len() {
            println!("FINITE");
            break;
        }

        if visited[pos] {
            println!("INFINITE");
            break;
        }

        visited[pos] = true;
    }
