#define N 1000100

int a[N];
int b[N];
int cnt[N];

int main() {
  int n;
  scanf("%d", &n);
  int i;
  for (i = 0; i < n; ++i) {
    int x;
    scanf("%d", &x);
    ++a[x];
  }
  for (i = N - 1; i > 0; --i) {
    cnt[i] += (a[i] + b[i]) / 2;
    if (a[i] % 2 == 1 && b[i] % 2 == 0 ||
        a[i] % 2 == 0 && b[i] % 2 == 1 && a[i] > 0) {
      ++b[i - 1];
    }
  }
  long long ans = 0;
  int last = -1;
  for (i = N - 1; i > 0; --i) {
    if (cnt[i] == 0) continue;
    if (last != -1) {
      --cnt[i];
      ans += (long long) last * i;
      last = -1;
    }
    ans += (long long) cnt[i] / 2 * i * i;
    if (cnt[i] % 2 == 1) {
      last = i;
    }
  }
  printf("%I64d\n", ans);
  return 0;
}

