use std::io::{self, Read};

const N: usize = 1000100;

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let n: usize = lines.next().unwrap().parse().unwrap();
    let mut a = vec![0; N];
    let mut b = vec![0; N];
    let mut cnt = vec![0; N];

    for line in lines.take(n) {
        let x: usize = line.parse().unwrap();
        a[x] += 1;
    }

    for i in (1..N).rev() {
        cnt[i] += (a[i] + b[i]) / 2;
        if (a[i] % 2 == 1 && b[i] % 2 == 0) || (a[i] % 2 == 0 && b[i] % 2 == 1 && a[i] > 0) {
            b[i - 1] += 1;
        }
    }

    let mut ans: i64 = 0;
    let mut last = -1;
    for i in (1..N).rev() {
        if cnt[i] == 0 {
            continue;
        }
        if last != -1 {
            cnt[i] -= 1;
            ans += (last as i64) * (i as i64);
            last = -1;
        }
        ans += (cnt[i] as i64 / 2) * (i as i64) * (i as i64);
        if cnt[i] % 2 == 1 {
            last = i as i32;
        }
    }

    println!("{}", ans);
}

