use std::io::{self, BufRead};

fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines().map(|l| l.unwrap());

    let n: usize = lines.next().unwrap().parse().unwrap();

    let mut t = 0;
    let mut points = [0; 6];
    for (i, point) in points.iter_mut().enumerate().take(6) {
        *point = lines.next().unwrap().split_whitespace().nth(i % 2).unwrap().parse().unwrap();
    }

    let mut x0 = points[0];
    let mut y0 = points[1];
    let mut x1 = points[2];
    let mut y1 = points[3];
    let mut x2 = points[4];
    let mut y2 = points[5];

    for _ in 0..n - 1 {
        if x2 != x0 {
            let r = (y2 - y0) as f32 / (x2 - x0) as f32;
            if (r > 0.0 && y0 == y1) || (r < 0.0 && x0 == x1) {
                t += 1;
            }
        }

        x0 = x1;
        y0 = y1;
        x1 = x2;
        y1 = y2;
        let next_point: Vec<i32> = lines.next().unwrap().split_whitespace().map(|s| s.parse().unwrap()).collect();
        x2 = next_point[0];
        y2 = next_point[1];
    }

    println!("{}", t);
}
